/**
 * Regenerates src/server/chain/artifacts.ts from Foundry build output.
 * Run: (cd contracts && forge build) && pnpm tsx scripts/chain/gen-artifacts.ts
 */
import { readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";

const names = ["MockToken", "DemoShop", "CounterSignAccount", "VulnerableWallet"] as const;
const root = resolve(__dirname, "../..");
let out =
  "// GENERATED by scripts/chain/gen-artifacts.ts from contracts/out (forge build). Do not edit by hand.\n";
for (const n of names) {
  const j = JSON.parse(readFileSync(resolve(root, `contracts/out/${n}.sol/${n}.json`), "utf8"));
  out += `export const ${n}Abi = ${JSON.stringify(j.abi)} as const;\n`;
  out += `export const ${n}Bytecode = "${j.bytecode.object}" as \`0x\${string}\`;\n`;
}
writeFileSync(resolve(root, "src/server/chain/artifacts.ts"), out);
console.log("wrote src/server/chain/artifacts.ts");
